import { Cable, Slack } from 'lucide-react';
import type { ReactNode } from 'react';

/**
 * Renders the official, coloured brand mark for a third-party
 * provider — Facebook blue, Mailchimp yellow, Stripe purple, etc.
 *
 * Every Simple Icons path is inlined here rather than pulled from a
 * package; the alternative (a 7 MB npm dep that pre-bundles 3,400
 * icons we don't use) was both wasteful and prone to install-time
 * timeouts on slower links. The marks we ship — 14 of them — total
 * well under 20 KB of bundled JS.
 *
 * LinkedIn + Slack come from Lucide because Simple Icons doesn't
 * ship those trademarks. Salesforce uses a hand-rolled minimal cloud
 * silhouette. Any unknown provider key falls back to a neutral
 * Cable icon so tables stay aligned.
 *
 * Pass `monochrome` to flip the brand mark to `currentColor` — useful
 * inside dense rows where the coloured mark clashes with the text.
 *
 * Paths and authoritative colours sourced from simple-icons.org
 * (CC0 1.0).
 */

