function TikTokBadge({ size, className, title }: BadgeProps): ReactNode {
    // Black rounded square. The note glyph is drawn three times with a
    // slight offset and the brand's cyan + magenta colours behind the
    // white top layer — that's the signature "RGB-split" look.
    const NOTE =
        'M16.1 7.05c-1.04-1-1.62-2.3-1.62-3.65h-2.35v9.5c-.04.94-.83 1.68-1.78 1.68-.59 0-1.13-.29-1.45-.74-.16-.22-.26-.49-.28-.78-.04-.7.37-1.36 1.05-1.6.16-.06.32-.09.49-.09v-2.4c-1.6-.04-3.05.96-3.6 2.5-.31.87-.21 1.84.27 2.62.62 1.01 1.72 1.65 2.92 1.65.74 0 1.44-.22 2.03-.6.78-.5 1.3-1.36 1.32-2.34v-4.95c.59.43 1.31.69 2.1.69v-2.35c-.39 0-.78-.07-1.15-.21Z';
    return (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            width={size}
            height={size}
            role="img"
            aria-label={title}
            className={className}
        >
            <title>{title}</title>
            <rect width="24" height="24" rx="5" fill="#000000" />
            <path d={NOTE} transform="translate(0.6 0.6)" fill="#25F4EE" />
            <path d={NOTE} transform="translate(-0.6 -0.6)" fill="#FE2C55" />
            <path d={NOTE} fill="#FFFFFF" />
        </svg>
    );
}

type BadgeProps = {
    size: number;
    className?: string;
    title: string;
};

const BADGE_RENDERERS: Record<
    string,
    (props: BadgeProps) => ReactNode
> = {
    facebook: FacebookBadge,
    instagram: InstagramBadge,
    linkedin: LinkedInBadge,
    tiktok: TikTokBadge,
};

export function BrandIcon({
    provider,
    size = 16,
    className,
    monochrome = false,
    title,
}: Props) {
    const raw = provider.toLowerCase().replace(/-/g, '_');
    const key = ALIASES[raw] ?? raw;

    // Full-colour official-style badges win over simple-icons for the
    // four marketing-priority brands — unless the caller asks for
    // monochrome rendering.
    if (!monochrome && BADGE_RENDERERS[key]) {
        const labelMap: Record<string, string> = {
            facebook: 'Facebook',
            instagram: 'Instagram',
            linkedin: 'LinkedIn',
            tiktok: 'TikTok',
        };
        return BADGE_RENDERERS[key]({
            size,
            className,
            title: title ?? labelMap[key],
        });
    }

    if (key === 'salesforce') {
        return (
            <SalesforceMark
                size={size}
                color={monochrome ? 'currentColor' : '#00A1E0'}
                className={className}
                title={title ?? 'Salesforce'}
            />
        );
    }

    if (key === 'slack') {
        return (
            <Slack
                size={size}
                color={monochrome ? 'currentColor' : '#4A154B'}
                className={className}
                aria-label={title ?? 'Slack'}
            />
        );
    }

    if (key === 'linkedin') {
        // Monochrome branch when caller passes monochrome=true.
        return (
            <SimpleIconMark
                icon={{
                    color: '#0A66C2',
                    label: 'LinkedIn',
                    path: 'M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.852 3.37-1.852 3.601 0 4.267 2.37 4.267 5.455v6.288zM5.337 7.433a2.062 2.062 0 01-2.063-2.065 2.063 2.063 0 112.063 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z',
                }}
                size={size}
                color="currentColor"
                className={className}
                title={title ?? 'LinkedIn'}
            />
        );
    }

    const simple = SIMPLE_ICONS[key];
    if (simple) {
        return (
            <SimpleIconMark
                icon={simple}
                size={size}
                color={monochrome ? 'currentColor' : simple.color}
                className={className}
                title={title ?? simple.label}
            />
        );
    }

    // Unknown provider — neutral plug/cable so rows still align.
    return (
        <Cable
            size={size}
            className={className}
            color="currentColor"
            aria-label={title ?? provider}
        />
    );
}
